/**
 * Normalize project data into the shared case study layout model.
 * Prefer explicit `project.caseStudy` when present.
 */
export function buildCaseStudy(project) {
  if (project.caseStudy) {
    const sections = withSectionIds(project.caseStudy.sections || []);
    return {
      title: project.caseStudy.title || project.title,
      meta: project.caseStudy.meta || null,
      metaFields: project.caseStudy.metaFields || null,
      heroImgs: project.caseStudy.heroImgs || null,
      heroVideo:
        project.caseStudy.heroVideo === null
          ? null
          : project.caseStudy.heroVideo ?? project.heroVideo,
      heroImg: project.caseStudy.heroImg ?? project.heroImg,
      mobileVideo:
        project.caseStudy.mobileVideo ?? project.mobileVideo ?? null,
      mobileCaption:
        project.caseStudy.mobileCaption ??
        project.mobileCaption ??
        null,
      // Explicit nav (e.g. Design System) wins; otherwise mirror section headers
      customNav: Boolean(project.caseStudy.nav?.length),
      nav: project.caseStudy.nav || buildNavFromSections(sections),
      sections,
    };
  }

  const sections = withSectionIds(buildSectionsFromLegacy(project));
  return {
    title: project.title,
    meta: project.metaFields?.length ? null : buildMetaLine(project),
    metaFields: project.metaFields || null,
    heroImgs: null,
    heroVideo: project.heroVideo,
    heroImg: project.heroImg,
    mobileVideo: project.mobileVideo || null,
    mobileCaption: project.mobileCaption || null,
    customNav: false,
    nav: buildNavFromSections(sections),
    sections,
  };
}

function slugify(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

function withSectionIds(sections) {
  return (sections || []).map((section, i) => ({
    ...section,
    id: section.id || slugify(section.title) || `section-${i}`,
  }));
}

function buildNavFromSections(sections) {
  return (sections || [])
    .filter((section) => section.title)
    .map((section) => ({
      id: section.id,
      label: section.navLabel || section.title,
    }));
}

function buildMetaLine(project) {
  return [project.subtitle, project.role, project.year, project.tools]
    .filter(Boolean)
    .join(' / ');
}

function buildSectionsFromLegacy(project) {
  const sections = [];

  if (project.problemPairs?.length) {
    sections.push({
      type: 'story-pairs',
      title: project.problemLabel || 'Why was this needed?',
      intro: project.problem || null,
      subtitle: project.problemSubtitle || null,
      pairs: project.problemPairs,
    });
  } else if (project.problem) {
    sections.push({
      type: 'prose',
      title: project.problemLabel || 'Why was this needed?',
      body: project.problem,
      img: project.problemImg || null,
    });
  }

  if (project.diagnosing?.length) {
    const imgs = project.diagnosing.flatMap((item) =>
      item.imgs || (item.img ? [item.img] : []),
    );
    const caption = project.diagnosing.map((item) => item.body).filter(Boolean).join(' ');
    if (imgs.length) {
      sections.push({
        type: 'image-grid',
        images: imgs.slice(0, 4),
        caption,
      });
    }
  }

  if (project.metrics?.length) {
    sections.push({
      type: 'results',
      title: 'The results',
      stats: project.metrics,
      // Only show cards when they add new copy; don't echo the stats from outcome.
      items: project.resultItems?.length ? project.resultItems : undefined,
    });
  } else if (project.outcome) {
    sections.push({
      type: 'results',
      title: 'The results',
      items: project.outcome.split('·').map((s) => s.trim()).filter(Boolean),
    });
  }

  if (project.extended?.research) {
    sections.push({
      type: 'prose',
      title: 'Research',
      body: project.extended.research,
      img: project.extended.researchImg || null,
    });
  } else if (project.extended?.researchSteps?.length) {
    const body = project.extended.researchSteps
      .map((step) => `${step.title}: ${step.items.join(' ')}`)
      .join(' ');
    sections.push({
      type: 'prose',
      title: 'Research',
      body,
    });
  } else if (project.extended?.context) {
    sections.push({
      type: 'prose',
      title: 'Research',
      body: project.extended.context,
    });
  }

  if (project.approach?.length) {
    sections.push({
      type: 'numbered',
      title: 'Process',
      items: project.approach,
    });
  }

  if (project.process?.length) {
    project.process.forEach((step) => {
      if (step.img) {
        sections.push({
          type: 'media-text',
          title: step.label,
          img: step.img,
          body: step.body,
          layout: step.layout || null,
        });
      } else {
        sections.push({
          type: 'prose',
          title: step.label,
          body: step.body,
        });
      }
    });
  } else if (project.extended?.siteMapPages?.length) {
    project.extended.siteMapPages.forEach((page) => {
      const img = page.img || page.imgs?.[0];
      if (img) {
        sections.push({
          type: 'media-text',
          title: page.title,
          img,
          body: page.description,
        });
      }
    });
  }

  const continueBody =
    project.extended?.reflection ||
    project.solution ||
    project.brief;

  if (continueBody) {
    sections.push({
      type: 'prose',
      title: 'Continue...',
      body: continueBody,
    });
  }

  return sections;
}
